CREATE TABLE IF NOT EXISTS settings (
  SettingKey VARCHAR(80) PRIMARY KEY,
  SettingValue LONGTEXT NOT NULL,
  UpdatedAt DATETIME NOT NULL,
  UpdatedBy VARCHAR(120) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS RecordChangeHistory (
  ChangeID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  TableName VARCHAR(80) NOT NULL, RecordID VARCHAR(80) NOT NULL,
  ChangedAt DATETIME NOT NULL, ChangedBy VARCHAR(120) NOT NULL,
  ChangedFieldsJSON LONGTEXT NOT NULL, BeforeJSON LONGTEXT NOT NULL, AfterJSON LONGTEXT NOT NULL,
  INDEX record_history (TableName, RecordID), INDEX changed_at (ChangedAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ArchivedRecords (
  ArchiveID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  TableName VARCHAR(80) NOT NULL, RecordID VARCHAR(80) NOT NULL,
  PreviousStatus VARCHAR(30) NOT NULL, ArchivedAt DATETIME NOT NULL,
  ArchivedBy VARCHAR(120) NOT NULL, Reason VARCHAR(500) NULL,
  RestoredAt DATETIME NULL, RestoredBy VARCHAR(120) NULL,
  INDEX archive_open (RestoredAt, ArchivedAt), INDEX archived_record (TableName, RecordID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS Users (
  UserID VARCHAR(20) PRIMARY KEY, Username VARCHAR(40) NOT NULL UNIQUE, Name VARCHAR(160) NOT NULL, Phone VARCHAR(60) NULL UNIQUE,
  Role VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NULL, EmployeeID VARCHAR(20) NULL, PasswordHash VARCHAR(255) NOT NULL, Status VARCHAR(20) NOT NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS Agreements (
  AgreementID VARCHAR(20) PRIMARY KEY, Company VARCHAR(200) NOT NULL, StartDate DATE NULL, EndDate DATE NULL,
  SecurityDeposit DECIMAL(16,2) NOT NULL DEFAULT 0, CommissionRate DECIMAL(7,2) NOT NULL DEFAULT 5, Status VARCHAR(20) NOT NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, Address TEXT NULL,
  ContactPerson VARCHAR(160) NULL, Phone VARCHAR(60) NULL, AlternatePhone VARCHAR(60) NULL, Email VARCHAR(190) NULL, FactoryName VARCHAR(200) NULL,
  FactoryAddress TEXT NULL, OfficeAddress TEXT NULL, TradeLicenseNo VARCHAR(120) NULL, TradeLicenseExpiry DATE NULL, BIN VARCHAR(80) NULL, TIN VARCHAR(80) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS AgreementDeposits (
  DepositID VARCHAR(20) PRIMARY KEY, AgreementID VARCHAR(20) NOT NULL, DueDate DATE NULL, Amount DECIMAL(16,2) NOT NULL,
  DepositDate DATE NULL, Description TEXT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, INDEX (AgreementID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS Products (
  ProductID VARCHAR(20) PRIMARY KEY, SKU VARCHAR(120) NOT NULL, ProductName VARCHAR(255) NOT NULL, ProductImageDataUrl MEDIUMTEXT NULL, Category VARCHAR(120) NULL,
  BaseUnit VARCHAR(60) NOT NULL, Status VARCHAR(20) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, ProductType VARCHAR(20) NOT NULL DEFAULT 'REGULAR',
  Variant TEXT NULL, OptionType VARCHAR(20) NOT NULL DEFAULT 'VARIANT', UnitOfMeasure VARCHAR(60) NULL, SupplierID VARCHAR(20) NULL, INDEX (SupplierID), INDEX (ProductName(100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ProductUnits (
  ProductUnitID VARCHAR(20) PRIMARY KEY, ProductID VARCHAR(20) NOT NULL, UnitName VARCHAR(60) NOT NULL,
  ConversionToBase DECIMAL(16,6) NOT NULL, PurchaseAllowed TINYINT(1) NOT NULL DEFAULT 1, SaleAllowed TINYINT(1) NOT NULL DEFAULT 1,
  UnitPrice DECIMAL(16,2) NOT NULL DEFAULT 0, Status VARCHAR(20) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, SalePrice DECIMAL(16,2) NOT NULL DEFAULT 0, PurchasePrice DECIMAL(16,2) NOT NULL DEFAULT 0,
  UNIQUE KEY product_unit (ProductID, UnitName)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS Dealers (
  DealerID VARCHAR(20) PRIMARY KEY, DealerName VARCHAR(200) NOT NULL, ContactPerson VARCHAR(160) NULL, Phone VARCHAR(60) NULL,
  Address TEXT NULL, Region VARCHAR(120) NULL, NID VARCHAR(80) NULL, TradeLicense VARCHAR(120) NULL, Status VARCHAR(20) NOT NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL,
  Area VARCHAR(120) NULL, DealerContact VARCHAR(160) NULL, DealerMobile VARCHAR(60) NULL, TSSContact VARCHAR(160) NULL,
  TSSMobile VARCHAR(60) NULL, DealerCode VARCHAR(20) NOT NULL UNIQUE, DealerPhotoDataUrl MEDIUMTEXT NULL,
  DealerClass VARCHAR(20) NOT NULL DEFAULT 'REGISTERED', CommissionRate DECIMAL(7,2) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS CustomerProfiles (
  CustomerID VARCHAR(20) PRIMARY KEY, CustomerName VARCHAR(200) NOT NULL, Mobile VARCHAR(20) NOT NULL,
  ContactPerson VARCHAR(160) NULL, Area VARCHAR(120) NULL, Address TEXT NULL, NID VARCHAR(80) NULL,
  Email VARCHAR(190) NULL, TradeLicense VARCHAR(120) NULL, Status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL,
  UNIQUE KEY customer_mobile (Mobile), INDEX (CustomerName), INDEX (Status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS CompanySupplies (
  SupplyID VARCHAR(20) PRIMARY KEY, AgreementID VARCHAR(20) NOT NULL, SupplyDate DATE NOT NULL, ReferenceNo VARCHAR(160) NULL,
  TotalAmount DECIMAL(16,2) NOT NULL, Status VARCHAR(30) NOT NULL, Notes TEXT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, PaymentStatus VARCHAR(20) NOT NULL, IdempotencyKey VARCHAR(120) NULL UNIQUE, INDEX (AgreementID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS CompanySupplyItems (
  SupplyItemID VARCHAR(20) PRIMARY KEY, SupplyID VARCHAR(20) NOT NULL, ProductID VARCHAR(20) NOT NULL, UnitName VARCHAR(60) NOT NULL,
  Quantity DECIMAL(16,4) NOT NULL, ConversionToBase DECIMAL(16,6) NOT NULL, BaseQuantity DECIMAL(16,4) NOT NULL,
  UnitPrice DECIMAL(16,2) NOT NULL, LineTotal DECIMAL(16,2) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  IsGift TINYINT(1) NOT NULL DEFAULT 0, Variant VARCHAR(160) NULL, PromotionType VARCHAR(20) NULL DEFAULT NULL, PromotionGifts TEXT NULL, INDEX (SupplyID), INDEX (ProductID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS GoodsReceipts (
  GRNID VARCHAR(20) PRIMARY KEY, SupplyID VARCHAR(20) NOT NULL, AgreementID VARCHAR(20) NOT NULL, ReceiptDate DATE NOT NULL,
  GateEntryNo VARCHAR(160) NULL, DeliveryChallan VARCHAR(160) NULL, Status VARCHAR(20) NOT NULL, Notes TEXT NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL,
  PostedAt DATETIME NULL, PostedBy VARCHAR(120) NULL, IdempotencyKey VARCHAR(120) NULL UNIQUE, INDEX (SupplyID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS GoodsReceiptItems (
  GRNItemID VARCHAR(20) PRIMARY KEY, GRNID VARCHAR(20) NOT NULL, SupplyItemID VARCHAR(20) NOT NULL, ProductID VARCHAR(20) NOT NULL,
  Variant VARCHAR(160) NULL, UnitName VARCHAR(60) NOT NULL, ConversionToBase DECIMAL(16,6) NOT NULL,
  OrderedQuantity DECIMAL(16,4) NOT NULL, PreviouslyAcceptedQuantity DECIMAL(16,4) NOT NULL, ReceivedQuantity DECIMAL(16,4) NOT NULL,
  AcceptedQuantity DECIMAL(16,4) NOT NULL, RejectedQuantity DECIMAL(16,4) NOT NULL, BaseReceivedQuantity DECIMAL(16,4) NOT NULL,
  BaseAcceptedQuantity DECIMAL(16,4) NOT NULL, BaseRejectedQuantity DECIMAL(16,4) NOT NULL, UnitCost DECIMAL(16,4) NOT NULL,
  RejectionReason TEXT NULL, IsGift TINYINT(1) NOT NULL DEFAULT 0, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, INDEX (GRNID), INDEX (SupplyItemID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS DealerSales (
  SaleID VARCHAR(20) PRIMARY KEY, AgreementID VARCHAR(20) NULL, DealerID VARCHAR(20) NULL, SaleDate DATE NOT NULL, InvoiceNo VARCHAR(100) NOT NULL,
  TotalAmount DECIMAL(16,2) NOT NULL, Status VARCHAR(20) NOT NULL, Notes TEXT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, CustomerType VARCHAR(20) NOT NULL, CustomerID VARCHAR(20) NULL,
  CustomerName VARCHAR(200) NULL, CustomerMobile VARCHAR(60) NULL, PaymentMode VARCHAR(10) NOT NULL DEFAULT 'DUE',
  CommissionRate DECIMAL(7,2) NULL, CommissionAmount DECIMAL(16,2) NOT NULL DEFAULT 0, INDEX (DealerID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS DealerSaleItems (
  SaleItemID VARCHAR(20) PRIMARY KEY, SaleID VARCHAR(20) NOT NULL, ProductID VARCHAR(20) NOT NULL, UnitName VARCHAR(60) NOT NULL,
  Quantity DECIMAL(16,4) NOT NULL, ConversionToBase DECIMAL(16,6) NOT NULL, BaseQuantity DECIMAL(16,4) NOT NULL,
  UnitPrice DECIMAL(16,2) NOT NULL, LineTotal DECIMAL(16,2) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  IsGift TINYINT(1) NOT NULL DEFAULT 0, Variant VARCHAR(160) NULL, PromotionType VARCHAR(20) NULL DEFAULT NULL, PromotionGifts TEXT NULL, INDEX (SaleID), INDEX (ProductID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS ProductReturns (
  ReturnID VARCHAR(20) PRIMARY KEY, AgreementID VARCHAR(20) NULL, DealerID VARCHAR(20) NULL, SaleID VARCHAR(20) NULL, ReturnDate DATE NOT NULL,
  Reason TEXT NULL, TotalAmount DECIMAL(16,2) NOT NULL, Status VARCHAR(20) NOT NULL, Notes TEXT NULL, CreatedAt DATETIME NOT NULL,
  CreatedBy VARCHAR(120) NOT NULL, ReturnType VARCHAR(20) NOT NULL, SupplyID VARCHAR(20) NULL, INDEX (SaleID), INDEX (SupplyID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ProductReturnItems (
  ReturnItemID VARCHAR(20) PRIMARY KEY, ReturnID VARCHAR(20) NOT NULL, ProductID VARCHAR(20) NOT NULL, UnitName VARCHAR(60) NOT NULL,
  Quantity DECIMAL(16,4) NOT NULL, ConversionToBase DECIMAL(16,6) NOT NULL, BaseQuantity DECIMAL(16,4) NOT NULL,
  UnitPrice DECIMAL(16,2) NOT NULL, LineTotal DECIMAL(16,2) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  IsGift TINYINT(1) NOT NULL DEFAULT 0, Variant VARCHAR(160) NULL, INDEX (ReturnID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS Payments (
  PaymentID VARCHAR(20) PRIMARY KEY, AgreementID VARCHAR(20) NULL, PayerType VARCHAR(20) NOT NULL, PayerID VARCHAR(40) NULL,
  ReceiverType VARCHAR(20) NOT NULL, ReceiverID VARCHAR(40) NULL, PaymentDate DATE NOT NULL, Amount DECIMAL(16,2) NOT NULL,
  PaymentMethod VARCHAR(80) NOT NULL, ReferenceNo VARCHAR(160) NULL, SaleID VARCHAR(20) NULL, Notes TEXT NULL, Status VARCHAR(20) NOT NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, SupplyID VARCHAR(20) NULL, EasyEntryID VARCHAR(20) NULL,
  INDEX (SaleID), INDEX (SupplyID), INDEX (PayerID), UNIQUE INDEX (EasyEntryID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS Expenses (
  ExpenseID VARCHAR(20) PRIMARY KEY, AgreementID VARCHAR(20) NULL, ExpenseDate DATE NOT NULL, Category VARCHAR(120) NOT NULL,
  Amount DECIMAL(16,2) NOT NULL, ReferenceNo VARCHAR(160) NULL, Description TEXT NULL, Status VARCHAR(20) NOT NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ProductCategories (CategoryID VARCHAR(20) PRIMARY KEY, CategoryName VARCHAR(120) NOT NULL, Status VARCHAR(20) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UNIQUE KEY category_name (CategoryName));
CREATE TABLE IF NOT EXISTS ExpenseCategories (ExpenseCategoryID VARCHAR(20) PRIMARY KEY, CategoryName VARCHAR(120) NOT NULL, Status VARCHAR(20) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UNIQUE KEY expense_category_name (CategoryName));
CREATE TABLE IF NOT EXISTS PaymentMethods (PaymentMethodID VARCHAR(20) PRIMARY KEY, MethodName VARCHAR(120) NOT NULL, Status VARCHAR(20) NOT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UNIQUE KEY payment_method_name (MethodName));
CREATE TABLE IF NOT EXISTS StockLedger (
  LedgerID VARCHAR(20) PRIMARY KEY, AgreementID VARCHAR(20) NOT NULL, ProductID VARCHAR(20) NOT NULL, TransactionDate DATE NOT NULL,
  TransactionType VARCHAR(40) NOT NULL, ReferenceID VARCHAR(80) NOT NULL, UnitName VARCHAR(60) NULL, Quantity DECIMAL(16,4) NOT NULL,
  BaseQuantityIn DECIMAL(16,4) NOT NULL DEFAULT 0, BaseQuantityOut DECIMAL(16,4) NOT NULL DEFAULT 0, BalanceQuantity DECIMAL(16,4) NOT NULL,
  UnitCost DECIMAL(16,4) NOT NULL DEFAULT 0, Description TEXT NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  IsGift TINYINT(1) NOT NULL DEFAULT 0, Variant VARCHAR(160) NULL, INDEX (AgreementID, ProductID), INDEX (ReferenceID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS InventoryDamageReversals (
  DamageID VARCHAR(80) NOT NULL PRIMARY KEY,
  ReversalReferenceID VARCHAR(80) NOT NULL UNIQUE,
  ReversedAt DATETIME NOT NULL,
  ReversedBy VARCHAR(120) NOT NULL,
  Reason VARCHAR(500) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS RecordReversalLinks (
  LinkID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, ArchiveID BIGINT UNSIGNED NOT NULL,
  EntityTable VARCHAR(80) NOT NULL, EntityID VARCHAR(80) NOT NULL, Kind VARCHAR(20) NOT NULL,
  OriginalID VARCHAR(80) NOT NULL, ReversalID VARCHAR(80) NOT NULL, PreviousStatus VARCHAR(30) NULL,
  INDEX record_reversal_archive (ArchiveID), INDEX record_reversal_entity (EntityTable,EntityID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS AuditLog (LogID VARCHAR(20) PRIMARY KEY, Timestamp DATETIME NOT NULL, UserEmail VARCHAR(120) NOT NULL, Action VARCHAR(40) NOT NULL, Module VARCHAR(80) NOT NULL, RecordID VARCHAR(40) NOT NULL, Description TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS Employees (
  EmployeeID VARCHAR(20) PRIMARY KEY, EmployeeCode VARCHAR(30) NOT NULL UNIQUE, UserID VARCHAR(20) NULL UNIQUE,
  DealerID VARCHAR(20) NULL, FullName VARCHAR(160) NOT NULL, Phone VARCHAR(40) NULL, Email VARCHAR(160) NULL,
  NID VARCHAR(80) NULL, JobTitle VARCHAR(120) NOT NULL, Department VARCHAR(120) NULL, JoiningDate DATE NULL,
  EmploymentType VARCHAR(30) NULL, MonthlySalary DECIMAL(16,2) NULL,
  Status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, INDEX (DealerID), INDEX (Status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRSourceRoster (
  SourceRosterID VARCHAR(24) PRIMARY KEY, EmployeeID VARCHAR(20) NOT NULL UNIQUE,
  SourceFile VARCHAR(255) NOT NULL, SourcePeriod CHAR(7) NULL, SourceRowNo INT NULL,
  SourceSRName VARCHAR(160) NULL, SourcePayeeName VARCHAR(160) NULL, SourceDealerName VARCHAR(200) NULL, SourceArea VARCHAR(160) NULL,
  TargetAmount DECIMAL(16,2) NULL, OnlineAmount DECIMAL(16,2) NULL, SalesAmount DECIMAL(16,2) NULL,
  AchievementRate DECIMAL(18,14) NULL, SourceSalaryTADA DECIMAL(16,2) NULL, CostSalesRate DECIMAL(18,14) NULL,
  SourceIncentive DECIMAL(16,2) NULL, SuperSmartSales DECIMAL(16,2) NULL, MegaCoilSales DECIMAL(16,2) NULL,
  DetergentSales DECIMAL(16,2) NULL, FoodSales DECIMAL(16,2) NULL, SourceNote TEXT NULL,
  SourceJoiningDate DATE NULL, ImportedAt DATETIME NOT NULL, ImportedBy VARCHAR(120) NOT NULL,
  UNIQUE KEY source_import_row (SourceFile, SourcePeriod, SourceRowNo), INDEX (SourceDealerName)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HREmployeeProfiles (
  EmployeeID VARCHAR(20) PRIMARY KEY, DateOfBirth DATE NOT NULL,
  BanglaName VARCHAR(160) NULL, FRIDNo VARCHAR(80) NULL, Gender VARCHAR(30) NULL, BloodGroup VARCHAR(10) NULL,
  MaritalStatus VARCHAR(30) NULL, FatherName VARCHAR(160) NULL, MotherName VARCHAR(160) NULL, SpouseName VARCHAR(160) NULL,
  Religion VARCHAR(60) NULL, Nationality VARCHAR(80) NULL, PhotoDataUrl MEDIUMTEXT NULL,
  CompanyName VARCHAR(160) NULL, Division VARCHAR(120) NULL, Section VARCHAR(120) NULL, PositionName VARCHAR(120) NULL, FingerID VARCHAR(80) NULL, WorkStatus VARCHAR(24) NULL,
  AutoAttendance TINYINT(1) NOT NULL DEFAULT 0, IgnoreForSalary TINYINT(1) NOT NULL DEFAULT 0,
  PresentAddress TEXT NULL, PresentAddressBangla TEXT NULL, PermanentAddress TEXT NULL, PermanentAddressBangla TEXT NULL,
  LivingArea VARCHAR(120) NULL, Thana VARCHAR(120) NULL, District VARCHAR(120) NULL,
  ShiftName VARCHAR(80) NULL, PayStructure VARCHAR(80) NULL, Grade VARCHAR(40) NULL, WeeklyHoliday VARCHAR(20) NULL,
  Designation VARCHAR(120) NULL, GrossSalary DECIMAL(16,2) NULL, BasicSalary DECIMAL(16,2) NULL,
  HouseRent DECIMAL(16,2) NULL, MedicalAllowance DECIMAL(16,2) NULL, TransportAllowance DECIMAL(16,2) NULL,
  LunchAllowance DECIMAL(16,2) NULL, FixedOT DECIMAL(16,2) NULL, GettingFixedOT TINYINT(1) NOT NULL DEFAULT 0,
  PFContributionPercent DECIMAL(7,3) NULL, BasicForPFPercent DECIMAL(7,3) NULL, PFEffectiveDate DATE NULL,
  OTActual TINYINT(1) NOT NULL DEFAULT 0, OTCompliance TINYINT(1) NOT NULL DEFAULT 0, GetBonus TINYINT(1) NOT NULL DEFAULT 0,
  SalesTarget DECIMAL(16,2) NULL, SalesAchievement DECIMAL(16,2) NULL, CommissionBase DECIMAL(16,2) NULL,
  CommissionRate DECIMAL(7,3) NULL, BonusAmount DECIMAL(16,2) NULL,
  EducationJSON MEDIUMTEXT NOT NULL, ExperienceJSON MEDIUMTEXT NULL, ExpertiseJSON MEDIUMTEXT NULL, NomineeJSON MEDIUMTEXT NULL,
  PaymentMode VARCHAR(40) NULL, AccountHolder VARCHAR(160) NULL, BankName VARCHAR(160) NULL, BankBranch VARCHAR(160) NULL,
  AccountNumber VARCHAR(80) NULL, RoutingNumber VARCHAR(80) NULL, MFSProvider VARCHAR(80) NULL, MFSNumber VARCHAR(40) NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL,
  INDEX (DateOfBirth), INDEX (District)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRAttendance (
  AttendanceID VARCHAR(24) PRIMARY KEY, EmployeeID VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NOT NULL,
  AttendanceDate DATE NOT NULL, AttendanceStatus VARCHAR(20) NOT NULL, PaidLeave TINYINT(1) NOT NULL DEFAULT 0,
  CheckIn TIME NULL, CheckOut TIME NULL, Notes VARCHAR(500) NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL,
  UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, UNIQUE KEY employee_day (EmployeeID, AttendanceDate), INDEX (DealerID, AttendanceDate)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRAchievements (
  AchievementID VARCHAR(24) PRIMARY KEY, EmployeeID VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NOT NULL,
  AchievementDate DATE NOT NULL, Title VARCHAR(180) NOT NULL, Category VARCHAR(80) NOT NULL, Description TEXT NULL,
  MetricValue DECIMAL(16,2) NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, INDEX (EmployeeID, AchievementDate)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRPayroll (
  PayrollID VARCHAR(24) PRIMARY KEY, EmployeeID VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NOT NULL,
  PayrollMonth CHAR(7) NOT NULL, WorkingDays INT NOT NULL, PaidDays DECIMAL(6,2) NOT NULL,
  MonthlySalary DECIMAL(16,2) NOT NULL, AttendancePay DECIMAL(16,2) NOT NULL,
  CommissionBase DECIMAL(16,2) NOT NULL DEFAULT 0, CommissionRate DECIMAL(8,5) NOT NULL DEFAULT 0,
  CommissionAmount DECIMAL(16,2) NOT NULL DEFAULT 0, TADA DECIMAL(16,2) NOT NULL DEFAULT 0,
  Incentive DECIMAL(16,2) NOT NULL DEFAULT 0, Additions DECIMAL(16,2) NOT NULL DEFAULT 0,
  Deductions DECIMAL(16,2) NOT NULL DEFAULT 0, LoanDeduction DECIMAL(16,2) NOT NULL DEFAULT 0, NetPay DECIMAL(16,2) NOT NULL, Status VARCHAR(20) NOT NULL DEFAULT 'APPROVED',
  DisbursedAmount DECIMAL(16,2) NULL, DisbursementMethod VARCHAR(40) NULL, DisbursedAt DATETIME NULL,
  DisbursedBy VARCHAR(120) NULL, DisbursementReference VARCHAR(160) NULL,
  CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL,
  UNIQUE KEY employee_month (EmployeeID, PayrollMonth), INDEX (DealerID, PayrollMonth, Status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS HRLeaveTypes (LeaveTypeID VARCHAR(24) PRIMARY KEY, DealerID VARCHAR(20) NOT NULL, TypeName VARCHAR(80) NOT NULL, IsPaid TINYINT(1) NOT NULL DEFAULT 1, AnnualEntitlement DECIMAL(6,2) NOT NULL DEFAULT 0, Status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UNIQUE KEY dealer_leave_type (DealerID, TypeName), INDEX (DealerID, Status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRLeaveRequests (LeaveRequestID VARCHAR(24) PRIMARY KEY, EmployeeID VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NOT NULL, LeaveTypeID VARCHAR(24) NOT NULL, StartDate DATE NOT NULL, EndDate DATE NOT NULL, Days DECIMAL(6,2) NOT NULL, Reason VARCHAR(600) NULL, Status VARCHAR(20) NOT NULL DEFAULT 'PENDING', DecisionNotes VARCHAR(500) NULL, DecidedAt DATETIME NULL, DecidedBy VARCHAR(120) NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, INDEX (DealerID, Status, StartDate), INDEX (EmployeeID, StartDate)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRLoans (LoanID VARCHAR(24) PRIMARY KEY, EmployeeID VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NOT NULL, LoanType VARCHAR(20) NOT NULL DEFAULT 'LOAN', RequestedAmount DECIMAL(16,2) NOT NULL, ApprovedAmount DECIMAL(16,2) NULL, MonthlyInstallment DECIMAL(16,2) NULL, OutstandingAmount DECIMAL(16,2) NULL, Reason VARCHAR(600) NULL, Status VARCHAR(20) NOT NULL DEFAULT 'PENDING', DisbursementMethod VARCHAR(40) NULL, DisbursementReference VARCHAR(160) NULL, DisbursedAt DATETIME NULL, DisbursedBy VARCHAR(120) NULL, DecisionNotes VARCHAR(500) NULL, DecidedAt DATETIME NULL, DecidedBy VARCHAR(120) NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, UpdatedAt DATETIME NOT NULL, UpdatedBy VARCHAR(120) NOT NULL, INDEX (DealerID, Status, CreatedAt), INDEX (EmployeeID, Status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRLoanRepayments (RepaymentID VARCHAR(24) PRIMARY KEY, LoanID VARCHAR(24) NOT NULL, PayrollID VARCHAR(24) NOT NULL, EmployeeID VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NOT NULL, PayrollMonth CHAR(7) NOT NULL, Amount DECIMAL(16,2) NOT NULL, Status VARCHAR(20) NOT NULL DEFAULT 'PENDING', PaidAt DATETIME NULL, CreatedAt DATETIME NOT NULL, UNIQUE KEY loan_payroll (LoanID, PayrollID), INDEX (DealerID, PayrollMonth, Status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRExpenseClaims (ClaimID VARCHAR(24) PRIMARY KEY, EmployeeID VARCHAR(20) NOT NULL, DealerID VARCHAR(20) NOT NULL, ExpenseDate DATE NOT NULL, Category VARCHAR(80) NOT NULL, Amount DECIMAL(16,2) NOT NULL, ApprovedAmount DECIMAL(16,2) NULL, Description VARCHAR(600) NULL, ReceiptReference VARCHAR(160) NULL, Status VARCHAR(20) NOT NULL DEFAULT 'PENDING', PaymentMethod VARCHAR(40) NULL, PaymentReference VARCHAR(160) NULL, PaidAt DATETIME NULL, PaidBy VARCHAR(120) NULL, DecisionNotes VARCHAR(500) NULL, DecidedAt DATETIME NULL, DecidedBy VARCHAR(120) NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, INDEX (DealerID, Status, ExpenseDate), INDEX (EmployeeID, ExpenseDate)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS HRPettyCashEntries (EntryID VARCHAR(24) PRIMARY KEY, DealerID VARCHAR(20) NOT NULL, EntryDate DATE NOT NULL, EntryType VARCHAR(20) NOT NULL, Category VARCHAR(80) NULL, EmployeeID VARCHAR(20) NULL, Amount DECIMAL(16,2) NOT NULL, ReferenceNo VARCHAR(160) NULL, Description VARCHAR(600) NULL, SourceClaimID VARCHAR(24) NULL, CreatedAt DATETIME NOT NULL, CreatedBy VARCHAR(120) NOT NULL, INDEX (DealerID, EntryDate), INDEX (SourceClaimID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
